local _, ns = ...

-------------------------------------------------------------------------------
--  Sane UI - Tooltips - Data - Quests
--  What the module knows of quests that the game does not tell an addon: who
--  gives a quest and who takes it back, what it asks before you may take it,
--  which creatures drop the things quests ask for, which items start a quest.
--  Quests.lua reads it; each string is taken apart only when a tooltip asks.
--
--  quest[id] = "levels;rule;races;classes;title"
--      levels   min-level-max: "20-30", "10-19-19"; one number when you may take it
--               at its own level ("5"); an unknown part is empty ("20-")
--      rule     what it asks first, each quest ID after its sign:
--                 +  must be done     /  one of these must be done
--                 !  closed to you once you have it or had it (a quest that
--                    excludes it, its chain's next step, the quest it leads to)
--               a side letter after the sign when it holds for one side: "!H162"
--      races    "" anyone, "A" or "H" a whole side, else the game's race IDs
--               ("1.7"); classes: the game's class IDs ("8", "1.2"), "" any
--  npc[id]  = groups of a letter and its entries, by spaces: "g7,15 t783 d60.2.33"
--      g  gives the quest         t  takes the quest back
--      d  drops a thing a quest's objective asks for: quest.objective[.chance]
--      s  drops an item that starts a quest: item.quest[.chance]
--  item[id] = "n60.2,90.1 b80"
--      n  a quest's objective asks for it: quest.objective    b  it starts the quest
--  An entry for one side only starts with its letter: "gH1718". A chance is how
--  often the creature drops it, in whole percent (0: below 1). A quest that
--  repeats is given by no NPC here: it shows while it is in your quest log.
-------------------------------------------------------------------------------
